<script setup lang="ts">
import { TALENTS, talentCost } from '../config/talent'
import { useGameStore } from '../stores/game'
import type { TalentKey } from '../types/game'
const store=useGameStore();const keys=Object.keys(TALENTS) as TalentKey[]
function effect(key:TalentKey,level:number){if(key==='luck')return `中奖概率 +${level}%`;if(key==='wealth')return `奖金 +${level*5}%`;if(key==='efficiency')return `刮奖时间减少 ${Math.min(80,level*5)}%`;if(key==='device')return `验票时间减少 ${Math.min(80,level*10)}%`;return level>=8?'完整自动化生产线':level>=5?'解锁自动购票':level>=3?'解锁自动刮奖':level>=2?'解锁自动领取':level>=1?'解锁自动提交':'逐步解锁自动化能力'}
</script>
<template><div class="page"><div class="page-heading"><div><span class="eyebrow">TALENT TREE</span><h1>天赋研究所</h1><p>分配天赋点，打造属于你的幸运经营策略。</p></div><div class="talent-points">✨ <b>{{store.game.player.talentPoints}}</b><small>可用天赋点</small></div></div><div class="talent-grid"><article v-for="key in keys" :key="key" class="panel talent-card"><div class="talent-top"><span class="talent-icon">{{TALENTS[key].icon}}</span><span class="level-tag">LV. {{store.game.talents[key]}} / {{TALENTS[key].maxLevel}}</span></div><h2>{{TALENTS[key].name}}系</h2><p>{{TALENTS[key].description}}</p><div class="talent-effect"><small>当前效果</small><b>{{effect(key,store.game.talents[key])}}</b></div><div class="talent-effect next"><small>下一级效果</small><b>{{effect(key,Math.min(TALENTS[key].maxLevel,store.game.talents[key]+1))}}</b></div><div class="talent-bottom"><span>🪙 {{talentCost(key,store.game.talents[key]).toLocaleString()}}</span><button class="btn primary" :disabled="store.game.talents[key]>=TALENTS[key].maxLevel||store.game.player.talentPoints<1||store.game.coins<talentCost(key,store.game.talents[key])" @click="store.upgradeTalent(key)">升级 · 1 点</button></div></article></div><div class="reset-row"><div><b>重新规划天赋</b><small>重置后返还所有天赋点，不返还升级消耗的金币。</small></div><button class="btn secondary" @click="store.resetTalents()">重置天赋</button></div></div></template>